record.field:
{
    "type": "object",
    "properties": {
        "search_text": {
            "type": "string",
            "description": "Name or phone to look for (min. 2 characters).",
            "maxLength": 100
        }
    },
    "required": [
        "search_text"
    ]
}

{
    "type": "object",
    "properties": {
        "conversation_id": {
            "type": "number",
            "description": "Id of the conversation, obtained with 'Find Conversation'."
        }
    },
    "required": [
        "conversation_id"
    ]
}

{
    "type": "object",
    "properties": {
        "partner_id": {
            "type": "number",
            "description": "Id of the contact, obtained with 'Find Partner'."
        },
        "text": {
            "type": "string",
            "description": "The message to send, final wording.",
            "maxLength": 1000
        },
        "account_id": {
            "type": "number",
            "description": "Id of the WhatsApp account (optional, only if the user chose one)."
        }
    },
    "required": [
        "partner_id",
        "text"
    ]
}
